<script setup lang="ts">
import { Link, useForm } from '@inertiajs/vue3'; import { Plus, Trash2 } from '@lucide/vue'; import { watch } from 'vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label';
type Unit={id:string;code:string;name:string;dimension:string}; type Item={id:string;name:string;type:string;presentations:{id:string;name:string;sku:string}[]}; type Product={id:string;name:string;sku:string}; type Option={value:string;label:string}; type Version={id:string;version_number:number;reference_flour_quantity:string;reference_flour_unit_id:string;expected_dough_yield:string;yield_unit_id:string;expected_waste_percentage:string;instructions:string|null;ingredients:any[];compatible_products:any[]}; type Recipe={id:string;code:string;name:string;description:string|null;is_active:boolean;version:Version};
const props=defineProps<{units:Unit[];items:Item[];products:Product[];roles:Option[];recipe?:Recipe}>(); const massUnits=props.units.filter(unit=>unit.dimension==='mass'); const defaultMass=massUnits.find(unit=>unit.code==='kg')?.id??massUnits[0]?.id??'';
const form=useForm({code:props.recipe?.code??'',name:props.recipe?.name??'',description:props.recipe?.description??'',is_active:props.recipe?.is_active??true,reference_flour_quantity:props.recipe?.version.reference_flour_quantity??'1',reference_flour_unit_id:props.recipe?.version.reference_flour_unit_id??defaultMass,expected_dough_yield:props.recipe?.version.expected_dough_yield??'1.6',yield_unit_id:props.recipe?.version.yield_unit_id??defaultMass,expected_waste_percentage:props.recipe?.version.expected_waste_percentage??'2',instructions:props.recipe?.version.instructions??'',ingredients:props.recipe?.version.ingredients?.map(line=>({...line}))??[{item_id:'',presentation_id:null,ingredient_role:'flour',quantity:'1',unit_id:defaultMass,baker_percentage:'100',allows_substitution:false},{item_id:'',presentation_id:null,ingredient_role:'other',quantity:'0.1',unit_id:defaultMass,baker_percentage:'10',allows_substitution:false}],compatible_products:props.recipe?.version.compatible_products?.map(product=>({...product,finishing_components:product.finishing_components??[]}))??[{presentation_id:'',dough_weight_per_unit:'80',dough_weight_unit_id:massUnits.find(unit=>unit.code==='g')?.id??defaultMass,baking_loss_percentage:'12',cost_weight_factor:'1',finishing_components:[]}]});
watch([()=>form.reference_flour_quantity,()=>form.reference_flour_unit_id],()=>{const flour=form.ingredients.find(line=>line.ingredient_role==='flour');if(flour){flour.quantity=form.reference_flour_quantity;flour.unit_id=form.reference_flour_unit_id;flour.baker_percentage='100';}});
const addIngredient=()=>form.ingredients.push({item_id:'',presentation_id:null,ingredient_role:'other',quantity:'0',unit_id:defaultMass,baker_percentage:null,allows_substitution:false}); const addProduct=()=>form.compatible_products.push({presentation_id:'',dough_weight_per_unit:'0',dough_weight_unit_id:defaultMass,baking_loss_percentage:'0',cost_weight_factor:'1',finishing_components:[]}); const submit=()=>props.recipe?form.put(`/recipes/${props.recipe.id}/versions/${props.recipe.version.id}`):form.post('/recipes');
</script>
<template><form class="grid gap-7" @submit.prevent="submit"><section class="grid gap-4 md:grid-cols-2"><div class="grid gap-2"><Label>Código</Label><Input v-model="form.code" required /></div><div class="grid gap-2"><Label>Nombre de la masa base</Label><Input v-model="form.name" required /></div><div class="grid gap-2 md:col-span-2"><Label>Descripción</Label><textarea v-model="form.description" rows="2" class="rounded-md border bg-transparent px-3 py-2 text-sm" /></div><label class="flex items-center gap-2 text-sm"><input v-model="form.is_active" type="checkbox" /> Receta activa</label></section><section class="grid gap-4"><div><h2 class="font-semibold">Referencia y rendimiento</h2><p class="text-xs text-muted-foreground">Esta base determina el escalado de cualquier producción.</p></div><div class="grid gap-4 md:grid-cols-3"><div class="grid gap-2"><Label>Harina de referencia</Label><Input v-model="form.reference_flour_quantity" type="number" min="0.000001" step="0.000001" required /></div><div class="grid gap-2"><Label>Unidad de harina</Label><select v-model="form.reference_flour_unit_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="unit in massUnits" :key="unit.id" :value="unit.id">{{ unit.name }} ({{ unit.code }})</option></select></div><div class="grid gap-2"><Label>Rendimiento esperado</Label><div class="flex gap-2"><Input v-model="form.expected_dough_yield" type="number" min="0.000001" step="0.000001" required /><select v-model="form.yield_unit_id" class="h-9 rounded-md border bg-transparent px-2 text-sm"><option v-for="unit in massUnits" :key="unit.id" :value="unit.id">{{ unit.code }}</option></select></div></div><div class="grid gap-2"><Label>Merma esperada %</Label><Input v-model="form.expected_waste_percentage" type="number" min="0" max="100" step="0.0001" /></div></div></section><section class="grid gap-3"><div class="flex justify-between"><div><h2 class="font-semibold">Ingredientes</h2><p class="text-xs text-muted-foreground">Debe existir exactamente una harina al 100 %.</p></div><Button type="button" variant="outline" size="sm" @click="addIngredient"><Plus /> Ingrediente</Button></div><div v-for="(line,index) in form.ingredients" :key="index" class="grid items-end gap-3 rounded-lg border p-3 lg:grid-cols-[1fr_10rem_9rem_8rem_8rem_auto]"><div class="grid gap-2"><Label>Artículo</Label><select v-model="line.item_id" required class="h-9 rounded-md border bg-transparent px-2 text-sm"><option value="" disabled>Selecciona</option><option v-for="item in items" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div class="grid gap-2"><Label>Rol</Label><select v-model="line.ingredient_role" class="h-9 rounded-md border bg-transparent px-2 text-sm"><option v-for="role in roles" :key="role.value" :value="role.value">{{ role.label }}</option></select></div><div class="grid gap-2"><Label>Cantidad</Label><Input v-model="line.quantity" type="number" min="0.000001" step="0.000001" /></div><div class="grid gap-2"><Label>Unidad</Label><select v-model="line.unit_id" class="h-9 rounded-md border bg-transparent px-2 text-sm"><option v-for="unit in units" :key="unit.id" :value="unit.id">{{ unit.code }}</option></select></div><div class="grid gap-2"><Label>% panadero</Label><Input v-model="line.baker_percentage" type="number" min="0" step="0.0001" /></div><Button type="button" variant="ghost" size="icon" :disabled="form.ingredients.length<=2" @click="form.ingredients.splice(index,1)"><Trash2 /></Button></div></section><section class="grid gap-3"><div class="flex justify-between"><div><h2 class="font-semibold">Productos compatibles</h2><p class="text-xs text-muted-foreground">Peso de masa cruda requerido para cada unidad.</p></div><Button type="button" variant="outline" size="sm" @click="addProduct"><Plus /> Producto</Button></div><div v-for="(product,index) in form.compatible_products" :key="index" class="grid items-end gap-3 rounded-lg border p-3 lg:grid-cols-[1fr_9rem_8rem_8rem_8rem_auto]"><div class="grid gap-2"><Label>Presentación</Label><select v-model="product.presentation_id" required class="h-9 rounded-md border bg-transparent px-2 text-sm"><option value="" disabled>Selecciona</option><option v-for="item in products" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div class="grid gap-2"><Label>Peso de masa</Label><Input v-model="product.dough_weight_per_unit" type="number" min="0.000001" step="0.000001" /></div><div class="grid gap-2"><Label>Unidad</Label><select v-model="product.dough_weight_unit_id" class="h-9 rounded-md border bg-transparent px-2 text-sm"><option v-for="unit in massUnits" :key="unit.id" :value="unit.id">{{ unit.code }}</option></select></div><div class="grid gap-2"><Label>Pérdida horno %</Label><Input v-model="product.baking_loss_percentage" type="number" min="0" max="100" step="0.0001" /></div><div class="grid gap-2"><Label>Factor costo</Label><Input v-model="product.cost_weight_factor" type="number" min="0.000001" step="0.000001" /></div><Button type="button" variant="ghost" size="icon" :disabled="form.compatible_products.length<=1" @click="form.compatible_products.splice(index,1)"><Trash2 /></Button></div></section><div class="grid gap-2"><Label>Instrucciones</Label><textarea v-model="form.instructions" rows="5" class="rounded-md border bg-transparent px-3 py-2 text-sm" /></div><p v-if="Object.keys(form.errors).length" class="text-sm text-destructive">Revisa los campos señalados. {{ Object.values(form.errors)[0] }}</p><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link :href="recipe?`/recipes/${recipe.id}`:'/recipes'">Cancelar</Link></Button><Button type="submit" :disabled="form.processing">Guardar borrador</Button></div></form></template>
